// Webhook endpoint form (create and edit) and the one-time secret panel shared by the 0.4 pages
// (webhook signing secrets, initial access tokens, secrets generated by a configuration apply).
import { type FormEvent, type ReactNode, useState } from "react";
import { ApiError } from "@/api/client";
import type { components } from "@/api/schema";
import { ProblemAlert } from "@/components/ProblemAlert";
import { CheckboxField, CheckboxGroup, TextField, fieldErrors } from "@/components/form";
import { Button } from "@/components/ui/button";

export type WebhookEndpoint = components["schemas"]["WebhookEndpointDto"];
export type WebhookEventType = components["schemas"]["WebhookEventType"];
type SubscribableEvent = Exclude<WebhookEventType, "test">;

/** Lifecycle events an endpoint can subscribe to (`test` is only sent by the test action). */
export const WEBHOOK_EVENTS: readonly { value: SubscribableEvent; label: string }[] = [
  { value: "user.created", label: "user.created" },
  { value: "user.updated", label: "user.updated" },
  { value: "user.deleted", label: "user.deleted" },
  { value: "user.email_verified", label: "user.email_verified" },
  { value: "user.email_changed", label: "user.email_changed" },
  { value: "user.password_changed", label: "user.password_changed" },
  { value: "session.created", label: "session.created" },
  { value: "session.revoked", label: "session.revoked" },
  { value: "session.logged_out", label: "session.logged_out" },
  { value: "organization.created", label: "organization.created" },
  { value: "organization.deleted", label: "organization.deleted" },
  { value: "organization.member_added", label: "organization.member_added" },
  { value: "organization.member_removed", label: "organization.member_removed" },
  { value: "organization.domain_verified", label: "organization.domain_verified" },
  { value: "organization.domain_unverified", label: "organization.domain_unverified" },
];

/** Client-side mirror of the API's endpoint name rule. The API decides. */
export const WEBHOOK_NAME_PATTERN = /^[a-z0-9][a-z0-9_-]{0,63}$/;

export interface WebhookFormValues {
  name: string;
  url: string;
  events: SubscribableEvent[];
  enabled: boolean;
}

export const NEW_WEBHOOK: WebhookFormValues = { name: "", url: "", events: [], enabled: true };

export function valuesFromEndpoint(e: WebhookEndpoint): WebhookFormValues {
  return {
    name: e.name,
    url: e.url,
    events: e.events.filter((ev): ev is SubscribableEvent => ev !== "test"),
    enabled: e.enabled,
  };
}

interface WebhookFormProps {
  mode: "create" | "edit";
  initial: WebhookFormValues;
  submitLabel: string;
  pending: boolean;
  error: unknown;
  onSubmit: (values: WebhookFormValues) => void;
}

export function WebhookForm({ mode, initial, submitLabel, pending, error, onSubmit }: WebhookFormProps) {
  const [values, setValues] = useState<WebhookFormValues>(initial);
  const [local, setLocal] = useState<Record<string, string>>({});
  const set = <K extends keyof WebhookFormValues>(key: K, value: WebhookFormValues[K]) =>
    setValues((v) => ({ ...v, [key]: value }));

  const server = fieldErrors(error);
  const errorsFor = (field: string) =>
    local[field] ? [{ message: local[field] }] : server[field];
  const known = ["name", "url", "events", "enabled"];
  const otherError =
    error && !(error instanceof ApiError && error.problem.errors.length > 0 && error.problem.errors.every((e) => known.includes(e.field)))
      ? error
      : null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const issues: Record<string, string> = {};
    if (!WEBHOOK_NAME_PATTERN.test(values.name))
      issues.name = "1-64 characters of a-z, 0-9, '_' or '-', starting with a letter or digit.";
    try {
      const u = new URL(values.url.trim());
      if (u.protocol !== "https:" && u.protocol !== "http:") issues.url = "Enter an https URL.";
    } catch {
      issues.url = "Enter an absolute URL (https://…).";
    }
    if (values.events.length === 0) issues.events = "Choose at least one event.";
    setLocal(issues);
    if (Object.keys(issues).length > 0) return;
    onSubmit({ ...values, url: values.url.trim() });
  };

  return (
    <form onSubmit={submit} className="space-y-4" noValidate aria-label="Webhook endpoint" data-testid="webhook-form">
      {otherError ? <ProblemAlert error={otherError} /> : null}
      <TextField
        label="Name"
        name="name"
        value={values.name}
        onChange={(e) => set("name", e.target.value)}
        hint="Unique in the tenant: a-z, 0-9, '_' and '-'."
        errors={errorsFor("name")}
        autoComplete="off"
        data-testid="webhook-name"
      />
      <TextField
        label="URL"
        name="url"
        type="url"
        value={values.url}
        onChange={(e) => set("url", e.target.value)}
        hint="An https URL. Private, loopback and link-local addresses are refused outside development mode."
        errors={errorsFor("url")}
        autoComplete="off"
        data-testid="webhook-url"
      />
      <CheckboxGroup
        legend="Events"
        options={WEBHOOK_EVENTS}
        value={values.events}
        onChange={(next) => set("events", next)}
        errors={errorsFor("events")}
      />
      <CheckboxField
        label="Enabled"
        name="enabled"
        checked={values.enabled}
        onChange={(e) => set("enabled", e.target.checked)}
        hint="A disabled endpoint receives no deliveries; events raised meanwhile are not queued for it."
        errors={errorsFor("enabled")}
      />
      <Button type="submit" disabled={pending} data-testid="webhook-submit">
        {pending ? "Saving…" : submitLabel}
      </Button>
      {mode === "create" && (
        <p className="text-muted-foreground text-xs">
          The signing secret is generated by the server and shown once after the endpoint is created.
        </p>
      )}
    </form>
  );
}

/**
 * A secret shown exactly once, with a copy button. The value lives only in the parent's component
 * state (never in a query or mutation cache); `onDone` clears it.
 */
export function OneTimeSecret({
  title,
  label,
  value,
  testId,
  onDone,
  children,
}: {
  title: string;
  label: string;
  value: string;
  testId: string;
  onDone: () => void;
  children?: ReactNode;
}) {
  const [status, setStatus] = useState<string | null>(null);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setStatus("Copied.");
    } catch {
      setStatus("Copy failed; select the value.");
    }
  };
  return (
    <div role="status" className="space-y-3 rounded-md border p-4 text-sm" data-testid={`${testId}-panel`}>
      <p className="font-medium">{title}</p>
      {children}
      <div className="space-y-1">
        <p className="text-muted-foreground">{label}</p>
        <code className="block rounded bg-muted px-2 py-1 break-all" data-testid={testId}>
          {value}
        </code>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Button type="button" variant="outline" size="sm" onClick={() => void copy()} data-testid={`${testId}-copy`}>
          Copy
        </Button>
        <Button type="button" size="sm" onClick={onDone} data-testid={`${testId}-done`}>
          I have stored it
        </Button>
        <span className="text-muted-foreground text-xs">{status}</span>
      </div>
    </div>
  );
}
